from pathlib import Path


def replace_once(path: str, old: str, new: str):
    p = Path(path)
    text = p.read_text()
    if text.count(old) != 1:
        raise SystemExit(f"anchor not found exactly once in {path}: {old[:120]!r}")
    p.write_text(text.replace(old, new, 1))

# Shared contracts for explicit action -> follow-up evidence links.
p = Path("packages/shared-types/src/qa-actions.ts")
text = p.read_text()
text += '''\n\nexport const CreateQaImprovementActionFollowUpSchema = z.object({\n  programmeId: z.string().trim().min(1),\n  evidenceId: z.string().uuid(),\n  note: z.string().trim().max(2000).default(""),\n});\nexport type CreateQaImprovementActionFollowUpInput = z.infer<typeof CreateQaImprovementActionFollowUpSchema>;\n\nexport const QaImprovementActionFollowUpListQuerySchema = z.object({\n  programmeId: z.string().trim().min(1),\n});\n\nexport interface QaImprovementActionFollowUpView {\n  id: string;\n  programmeId: string;\n  actionId: string;\n  evidenceId: string;\n  evidenceTitle: string;\n  evidenceStatus: "draft" | "ready" | "reviewed";\n  note: string;\n  linkedById: string;\n  linkedAt: string;\n}\n'''
